import{_ as a,o as e,c as r,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"认识 Hearth","description":"Hearth 的产品定位、目标用户、核心能力与当前状态。","frontmatter":{"title":"认识 Hearth","description":"Hearth 的产品定位、目标用户、核心能力与当前状态。","outline":[2,3]},"headers":[],"relativePath":"guide/what-is-hearth.md","filePath":"guide/what-is-hearth.md","lastUpdated":null}'),l={name:"guide/what-is-hearth.md"};function i(s,t,o,h,d,p){return e(),r("div",null,[...t[0]||(t[0]=[n(`<p class="eyebrow">PROJECT INTRODUCTION</p><h1 id="hearth-把数字劳动变成可靠任务" tabindex="-1">Hearth：把数字劳动变成可靠任务 <a class="header-anchor" href="#hearth-把数字劳动变成可靠任务" aria-label="Permalink to &quot;Hearth：把数字劳动变成可靠任务&quot;">​</a></h1><p class="lead">Hearth 是一个单用户、自托管、长期驻留、低打扰、低 Token 的通用个人 Agent OS。它的目标不是制造另一个需要看管的聊天窗口，而是让重复的数字劳动可以被放心地托付、验证和恢复。</p><h2 id="一句话定位" tabindex="-1">一句话定位 <a class="header-anchor" href="#一句话定位" aria-label="Permalink to &quot;一句话定位&quot;">​</a></h2><blockquote><p><strong>Hearth 是一个拥有个人上下文、持久执行、真实工具和多设备入口的通用个人 Agent OS；它把人从重复的数字劳动中解放出来，而不是制造另一个需要看管的聊天窗口。</strong></p></blockquote><p>产品名是 Hearth，仓库为 <code>hearth-os</code>，命令行为 <code>hearth</code>，常驻服务为 <code>hearthd</code>，包命名空间为 <code>@hearth/*</code>。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>现有 Agent 往往能完成一次演示，却很难长期使用。问题通常不在模型能力，而在模型之外：</p><ul><li>任务状态保存在聊天记录里，崩溃或换设备后无法可靠恢复；</li><li>外部副作用缺少审批、幂等、回执和对账；</li><li>权限、凭据和记忆没有清晰边界；</li><li>用户必须理解 Agent 的内部结构，才能判断它是否真的完成；</li><li>每次任务都重复读取大量上下文，Token 成本不可控；</li><li>前端被当成后置包装层，用户只能面对日志或 CLI。</li></ul><p>Hearth 把这些能力放到产品中心：<strong>控制面、持久执行、并列执行器、记忆、进化、体验与评估</strong>。</p><h2 id="它不是什么" tabindex="-1">它不是什么 <a class="header-anchor" href="#它不是什么" aria-label="Permalink to &quot;它不是什么&quot;">​</a></h2><ul><li>不是另一个 Coding Agent；</li><li>不是只会转发提示词的 Codex 套壳；</li><li>不是把所有权限交给模型的黑盒自动化；</li><li>不是企业多租户 Agent 平台；</li><li>不是需要用户每天维护提示词、插件和工作流的工具。</li></ul><p>Codex 在 Hearth 中是强大的<strong>并列执行器</strong>，不是产品本体，也不是唯一执行大脑。</p><h2 id="一个逻辑-agent-多设备执行" tabindex="-1">一个逻辑 Agent，多设备执行 <a class="header-anchor" href="#一个逻辑-agent-多设备执行" aria-label="Permalink to &quot;一个逻辑 Agent，多设备执行&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个逻辑 Hearth</span></span>
<span class="line"><span>  ├─ 一个主 Gateway / Control Plane</span></span>
<span class="line"><span>  ├─ 一个 Event Log / 单写者</span></span>
<span class="line"><span>  ├─ 多台设备上的 agentd</span></span>
<span class="line"><span>  ├─ 手机作为查看、审批、接管、发起入口</span></span>
<span class="line"><span>  └─ 每个设备注册自己的能力</span></span></code></pre></div><p>设备只提供执行能力和入口，不复制身份、事实源和授权。所有事实进入 Event Log；所有外部副作用经过 outbox、幂等键和 Receipt；所有界面状态都是投影，不是事实源。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>解决的问题</th></tr></thead><tbody><tr><td>任务控制面</td><td>决定做什么、是否允许、何时打扰、如何恢复</td></tr><tr><td>持久执行内核</td><td>把意图变成可恢复、可审计、可回执的执行</td></tr><tr><td>并列执行器</td><td>按能力、风险和 Token 成本选择 Codex、Native、Connector、Browser、GUI 或 Human</td></tr><tr><td>记忆与进化</td><td>让人物、项目、偏好、承诺和经验可被安全召回，让重复成功沉淀成受控技能</td></tr><tr><td>体验平面</td><td>用任务卡、审批和产物承载交互，而不是无穷聊天记录</td></tr><tr><td>安全与评估</td><td>用验证器、红队、故障注入和阶段门槛证明“真的能做”</td></tr></tbody></table><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><p>仓库目前包含 <strong>v3.2 产品、架构、安全与交付路线图</strong>。实现尚未开始；Stage 0 与 Stage 1 将按照路线图中的纵向切片计划推进。</p><p>继续阅读：</p><ul><li><a href="/hearth-os/product/definition.html">产品定义与边界</a></li><li><a href="/hearth-os/architecture/">系统设计总览</a></li><li><a href="/hearth-os/delivery/roadmap.html">分阶段产品路线图</a></li><li><a href="/hearth-os/guide/project-status.html">项目状态</a></li></ul>`,22)])])}const g=a(l,[["render",i]]);export{u as __pageData,g as default};
